  "{n} fixes from checking": [{ one: "{n} виправлення після перевірки", few: "{n} виправлення після перевірки", many: "{n} виправлень після перевірки", other: "{n} виправлення після перевірки" }, { one: "{n} corrección tras revisar", other: "{n} correcciones tras revisar" }, "检查后修正 {n} 处"],
  "{n} hours ago": [{ one: "{n} годину тому", few: "{n} години тому", many: "{n} годин тому", other: "{n} години тому" }, { one: "hace {n} hora", other: "hace {n} horas" }, "{n} 小时前"],
  "{n} items": [{ one: "{n} елемент", few: "{n} елементи", many: "{n} елементів", other: "{n} елементи" }, { one: "{n} elemento", other: "{n} elementos" }, "{n} 项"],
  "{n} lines": [{ one: "{n} рядок", few: "{n} рядки", many: "{n} рядків", other: "{n} рядки" }, { one: "{n} línea", other: "{n} líneas" }, "{n} 行"],
  "{n} lines edited by hand. Transcribing again keeps them.": [{ one: "{n} рядок змінено вручну. Повторна транскрипція його збереже.", few: "{n} рядки змінено вручну. Повторна транскрипція їх збереже.", many: "{n} рядків змінено вручну. Повторна транскрипція їх збереже.", other: "{n} рядки змінено вручну. Повторна транскрипція їх збереже." }, { one: "{n} línea editada a mano. Retranscribir la conserva.", other: "{n} líneas editadas a mano. Retranscribir las conserva." }, "{n} 行已手动编辑。重新转录会保留。"],
