  "{n} meetings ahead": [{ one: "{n} зустріч попереду", few: "{n} зустрічі попереду", many: "{n} зустрічей попереду", other: "{n} зустрічі попереду" }, { one: "{n} reunión por delante", other: "{n} reuniones por delante" }, "前面还有 {n} 个会议"],
  "{n} notes": [{ one: "{n} нотатка", few: "{n} нотатки", many: "{n} нотаток", other: "{n} нотатки" }, { one: "{n} nota", other: "{n} notas" }, "{n} 条笔记"],
  "{n} other tracks": [{ one: "ще {n} доріжка", few: "ще {n} доріжки", many: "ще {n} доріжок", other: "ще {n} доріжки" }, { one: "{n} pista más", other: "{n} pistas más" }, "另外 {n} 条音轨"],
  "{n} other vaults": [{ one: "{n} інше сховище", few: "{n} інші сховища", many: "{n} інших сховищ", other: "{n} інші сховища" }, { one: "{n} otra bóveda", other: "{n} otras bóvedas" }, "{n} 个其他保险库"],
  "{n} script readings": [{ one: "{n} читання сценарію", few: "{n} читання сценарію", many: "{n} читань сценарію", other: "{n} читання сценарію" }, { one: "{n} lectura de guion", other: "{n} lecturas de guion" }, "{n} 次脚本朗读"],
  "{n} takes": [{ one: "{n} спроба", few: "{n} спроби", many: "{n} спроб", other: "{n} спроби" }, { one: "{n} toma", other: "{n} tomas" }, "{n} 次录制"],
