  "{name} is added and reads from now on.": ["{name} додано, і тепер він читає.", "{name} se añadió y lee desde ahora.", "{name} 已添加，现在开始朗读。"],
  "{name} is ready, and reads {1} from now on.": ["{name} готовий і тепер читає {1}.", "{name} está lista y lee {1} desde ahora.", "{name} 已就绪，现在开始朗读{1}。"],
  "{name} is ready, and reads from now on.": ["{name} готовий і тепер читає.", "{name} está lista y lee desde ahora.", "{name} 已就绪，现在开始朗读。"],
