  "{name}: coming soon": ["{name}: незабаром", "{name}: próximamente", "{name}：即将推出"],
  "{names} needs the {name} speech model, {size}. Downloaded once, kept on this device.": ["Для {names} потрібна модель мовлення {name}, {size}. Завантажується один раз і зберігається на пристрої.", "{names} necesita el modelo de voz {name}, {size}. Se descarga una vez y queda en este dispositivo.", "{names} 需要 {name} 语音模型（{size}）。只需下载一次，保存在本设备上。"],
  "{names}. Change language": ["{names}. Змінити мову", "{names}. Cambiar idioma", "{names}。更改语言"],
  "{offset} against the meeting": ["{offset} відносно зустрічі", "{offset} respecto a la reunión", "相对会议 {offset}"],
  "{ready} of 4 ready. Any one opens your vault; the more you have, the less one lost matters.": ["Готово {ready} з 4. Будь-який відкриває сховище; що більше їх, то менше важить втрата одного.", "{ready} de 4 listas. Cualquiera abre tu bóveda; cuantas más tengas, menos importa perder una.", "已就绪 {ready}/4。任一方式均可打开保险库；方式越多，丢失一种的影响越小。"],
  "{shown} of {n} versions": [{ one: "{shown} з {n} версії", few: "{shown} з {n} версій", many: "{shown} з {n} версій", other: "{shown} з {n} версій" }, { one: "{shown} de {n} versión", other: "{shown} de {n} versiones" }, "{shown}/{n} 个版本"],
  "{size}, then offline": ["{size}, далі офлайн", "{size}, luego sin conexión", "{size}，之后可离线"],
  "{speech} (not downloaded)": ["{speech} (не завантажено)", "{speech} (sin descargar)", "{speech}（未下载）"],
  "{speechSpeed}. Dictation, commands and transcripts.": ["{speechSpeed}. Диктування, команди й транскрипти.", "{speechSpeed}. Dictado, comandos y transcripciones.", "{speechSpeed}。听写、命令和转录。"],
  "{what}. Click to change how {name} sounds.": ["{what}. Натисніть, щоб змінити звучання {name}.", "{what}. Pulsa para cambiar cómo suena {name}.", "{what}。点击更改 {name} 的声音。"],
  "{words}. Summaries, action items and templates.": ["{words}. Підсумки, завдання й шаблони.", "{words}. Resúmenes, tareas y plantillas.", "{words}。摘要、待办事项和模板。"],
